import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const fakeUpdate = (id, qty) => new Promise((res) => setTimeout(() => res({ id: id, qty: qty }), 200));

function App() {
  const [items, setItems] = useState([
    { id: "c1", name: "Чихэвч", qty: 1 }, { id: "c2", name: "Ном", qty: 2 },
  ]);

  function inc(id, current) {
    fakeUpdate(id, current + 1).then((updated) => {
      setItems((prev) => prev.map((x) => (x.id === id ? { ...x, qty: updated.qty } : x)));
    });
  }

  return (
    <View style={styles.s}>
      {items.map((it) => (
        <View key={it.id} style={styles.row}>
          <Text>{it.name}</Text>
          <Text nativeID={"qty-" + it.id} style={styles.qty}>{it.qty}</Text>
          <Pressable nativeID={"inc-" + it.id} style={styles.btn} onPress={() => inc(it.id, it.qty)}><Text style={styles.btnText}>+</Text></Pressable>
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  row: { flexDirection: "row", alignItems: "center", gap: 14, paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
  qty: { fontSize: 18, fontWeight: "bold", minWidth: 24, textAlign: "center" },
  btn: { backgroundColor: "#2563eb", width: 36, height: 36, borderRadius: 8, alignItems: "center", justifyContent: "center" },
  btnText: { color: "#fff", fontWeight: "bold", fontSize: 18 },
});

registerRootComponent(App);
